import './styles.css';
import { useState } from 'react';

interface Question {
  id: string;
  category: string;
  question: string;
  hint: string;
  goodSign: string;
  warningSign: string;
}

const questions: Question[] = [
  {
    id: 'problem-fit',
    category: 'Problem Clarity',
    question: 'Can you describe the specific problem AI would solve in one sentence?',
    hint: 'Vague goals like "use AI to be innovative" often lead to failed projects.',
    goodSign: 'The problem is concrete: "We need to process 10,000 survey responses faster."',
    warningSign: 'The goal is fuzzy: "We want to leverage AI for impact."'
  },
  {
    id: 'data-quality',
    category: 'Data Readiness',
    question: 'Do you have clean, organized data to train or feed the AI?',
    hint: 'AI is only as good as its data. Messy records = messy results.',
    goodSign: 'Data is structured, consistent, and covers representative cases.',
    warningSign: 'Data is scattered across spreadsheets, incomplete, or poorly labeled.'
  },
  {
    id: 'data-bias',
    category: 'Data Readiness',
    question: 'Does your data represent the communities you serve—including marginalized groups?',
    hint: 'AI trained on biased data will make biased decisions.',
    goodSign: 'Data collection actively includes underrepresented populations.',
    warningSign: 'Historical data over-represents some groups and excludes others.'
  },
  {
    id: 'human-oversight',
    category: 'Human Control',
    question: 'Will humans review AI outputs before they affect real people?',
    hint: 'Critical decisions should never be fully automated.',
    goodSign: 'Staff will verify AI recommendations before acting on them.',
    warningSign: 'AI outputs will be used directly without human checks.'
  },
  {
    id: 'failure-impact',
    category: 'Risk Assessment',
    question: 'If the AI makes a mistake, what happens to the people you serve?',
    hint: 'Low-stakes errors are annoying. High-stakes errors can harm lives.',
    goodSign: 'Errors cause inconvenience but no lasting harm.',
    warningSign: 'Errors could affect health, safety, legal status, or resources.'
  },
  {
    id: 'capacity',
    category: 'Organizational Capacity',
    question: 'Do you have staff who can maintain, monitor, and update the AI system?',
    hint: 'AI isn\'t set-and-forget. It needs ongoing care.',
    goodSign: 'Dedicated staff with training budget for ongoing maintenance.',
    warningSign: 'No one owns this after launch, or it depends on one person.'
  },
  {
    id: 'community-input',
    category: 'Inclusion',
    question: 'Have affected communities been consulted about using AI?',
    hint: 'Building for people without them often backfires.',
    goodSign: 'Community members shaped requirements and will test the system.',
    warningSign: 'The decision was made internally without community input.'
  },
  {
    id: 'alternatives',
    category: 'Right Tool',
    question: 'Have you seriously considered non-AI alternatives?',
    hint: 'Sometimes a spreadsheet, a phone tree, or more staff is the right answer.',
    goodSign: 'AI was chosen after comparing costs/benefits of simpler options.',
    warningSign: 'AI was the starting point, not the conclusion of analysis.'
  }
];

type Response = 'yes' | 'partial' | 'no' | null;

const categoryColors: Record<string, string> = {
  'Problem Clarity': '#3b82f6',
  'Data Readiness': '#8b5cf6',
  'Human Control': '#f59e0b',
  'Risk Assessment': '#ef4444',
  'Organizational Capacity': '#10b981',
  'Inclusion': '#ec4899',
  'Right Tool': '#06b6d4'
};

function QuestionCard({
  question,
  response,
  onRespond,
  isExpanded,
  onToggle
}: {
  question: Question;
  response: Response;
  onRespond: (r: Response) => void;
  isExpanded: boolean;
  onToggle: () => void;
}) {
  const color = categoryColors[question.category];

  return (
    <div className={`question-card ${isExpanded ? 'expanded' : ''} ${response ? 'answered' : ''}`}>
      <div className="card-header" onClick={onToggle}>
        <div className="header-left">
          <span className="category-pill" style={{ backgroundColor: color }}>
            {question.category}
          </span>
          <p className="question-text">{question.question}</p>
        </div>
        <div className="header-right">
          {response && (
            <span className={`status-dot ${response}`}>
              {response === 'yes' ? '✓' : response === 'partial' ? '~' : '✗'}
            </span>
          )}
          <span className="expand-btn">{isExpanded ? '−' : '+'}</span>
        </div>
      </div>

      {isExpanded && (
        <div className="card-body">
          <p className="hint">{question.hint}</p>

          <div className="signals">
            <div className="signal good">
              <span className="signal-icon">✓</span>
              <div>
                <strong>Good sign</strong>
                <p>{question.goodSign}</p>
              </div>
            </div>
            <div className="signal warning">
              <span className="signal-icon">!</span>
              <div>
                <strong>Warning sign</strong>
                <p>{question.warningSign}</p>
              </div>
            </div>
          </div>

          <div className="response-row">
            <span className="response-label">Your assessment:</span>
            <div className="response-buttons">
              <button
                className={`resp-btn yes ${response === 'yes' ? 'selected' : ''}`}
                onClick={() => onRespond('yes')}
              >
                Yes
              </button>
              <button
                className={`resp-btn partial ${response === 'partial' ? 'selected' : ''}`}
                onClick={() => onRespond('partial')}
              >
                Partially
              </button>
              <button
                className={`resp-btn no ${response === 'no' ? 'selected' : ''}`}
                onClick={() => onRespond('no')}
              >
                No
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

function ResultsPanel({ responses }: { responses: Record<string, Response> }) {
  const answered = Object.values(responses).filter(r => r !== null).length;
  const yesCount = Object.values(responses).filter(r => r === 'yes').length;
  const partialCount = Object.values(responses).filter(r => r === 'partial').length;
  const noCount = Object.values(responses).filter(r => r === 'no').length;

  let verdict = 'incomplete';
  let verdictMessage = 'Answer all questions for your assessment.';
  let verdictColor = '#6b7280';

  if (answered === questions.length) {
    if (noCount >= 3) {
      verdict = 'not-ready';
      verdictMessage = 'Major gaps to address. Consider alternatives or build foundation first.';
      verdictColor = '#ef4444';
    } else if (noCount >= 1 || partialCount >= 4) {
      verdict = 'proceed-caution';
      verdictMessage = 'Address the gaps before committing significant resources.';
      verdictColor = '#f59e0b';
    } else {
      verdict = 'ready';
      verdictMessage = 'Foundations look solid. Proceed with thoughtful implementation.';
      verdictColor = '#10b981';
    }
  }

  const gapsToAddress = questions.filter(q => responses[q.id] === 'no');
  const areasToStrengthen = questions.filter(q => responses[q.id] === 'partial');

  return (
    <div className="results-panel">
      <h3>Fit Assessment</h3>

      <div className="score-row">
        <div className="score-item yes">
          <span className="score-num">{yesCount}</span>
          <span className="score-lbl">Ready</span>
        </div>
        <div className="score-item partial">
          <span className="score-num">{partialCount}</span>
          <span className="score-lbl">Partial</span>
        </div>
        <div className="score-item no">
          <span className="score-num">{noCount}</span>
          <span className="score-lbl">Gap</span>
        </div>
      </div>

      <div className="verdict-box" style={{ borderColor: verdictColor, backgroundColor: verdictColor + '15' }}>
        <p style={{ color: verdictColor }}>{verdictMessage}</p>
      </div>

      {gapsToAddress.length > 0 && (
        <div className="gaps-section">
          <h4>Gaps to Address</h4>
          <ul>
            {gapsToAddress.map(q => (
              <li key={q.id}>{q.category}: {q.question}</li>
            ))}
          </ul>
        </div>
      )}

      {areasToStrengthen.length > 0 && answered === questions.length && (
        <div className="strengthen-section">
          <h4>Areas to Strengthen</h4>
          <ul>
            {areasToStrengthen.map(q => (
              <li key={q.id}>{q.category}</li>
            ))}
          </ul>
        </div>
      )}
    </div>
  );
}

export default function App() {
  const [responses, setResponses] = useState<Record<string, Response>>(
    Object.fromEntries(questions.map(q => [q.id, null]))
  );
  const [expandedId, setExpandedId] = useState<string | null>(questions[0].id);

  const handleRespond = (id: string, response: Response) => {
    setResponses(prev => ({ ...prev, [id]: response }));
  };

  return (
    <div className="app">
      <div className="header">
        <h1>AI Use Case Fit Assessment</h1>
        <p>Is AI right for your civil society project?</p>
      </div>

      <div className="main-grid">
        <div className="questions-list">
          {questions.map(q => (
            <QuestionCard
              key={q.id}
              question={q}
              response={responses[q.id]}
              onRespond={(r) => handleRespond(q.id, r)}
              isExpanded={expandedId === q.id}
              onToggle={() => setExpandedId(expandedId === q.id ? null : q.id)}
            />
          ))}
        </div>

        <ResultsPanel responses={responses} />
      </div>

      <div className="footer-note">
        <strong>Remember:</strong> "No" doesn't mean never—it means not yet. Build the foundation, then revisit.
      </div>
    </div>
  );
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: system-ui, -apple-system, sans-serif;
  background: linear-gradient(135deg, #059669 0%, #10b981 100%);
  min-height: 100vh;
  padding: 1.5rem 1rem;
}

.app {
  max-width: 1000px;
  margin: 0 auto;
}

.header {
  text-align: center;
  margin-bottom: 1.5rem;
}

h1 {
  color: white;
  font-size: 1.6rem;
  margin-bottom: 0.25rem;
}

.header p {
  color: rgba(255, 255, 255, 0.9);
  font-size: 0.95rem;
}

.main-grid {
  display: grid;
  grid-template-columns: 1fr 300px;
  gap: 1rem;
  margin-bottom: 1rem;
}

@media (max-width: 800px) {
  .main-grid {
    grid-template-columns: 1fr;
  }
}

.questions-list {
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
}

.question-card {
  background: white;
  border-radius: 0.75rem;
  overflow: hidden;
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.1);
  transition: box-shadow 0.2s;
}

.question-card.expanded {
  box-shadow: 0 4px 20px rgba(0, 0, 0, 0.15);
}

.card-header {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  padding: 0.75rem 1rem;
  cursor: pointer;
  gap: 0.75rem;
}

.card-header:hover {
  background: #f9fafb;
}

.header-left {
  flex: 1;
}

.category-pill {
  display: inline-block;
  font-size: 0.6rem;
  font-weight: 600;
  color: white;
  padding: 0.15rem 0.4rem;
  border-radius: 0.25rem;
  margin-bottom: 0.35rem;
  text-transform: uppercase;
}

.question-text {
  font-size: 0.9rem;
  color: #1f2937;
  line-height: 1.4;
}

.header-right {
  display: flex;
  align-items: center;
  gap: 0.5rem;
}

.status-dot {
  width: 22px;
  height: 22px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 0.75rem;
  font-weight: 600;
}

.status-dot.yes {
  background: #d1fae5;
  color: #059669;
}

.status-dot.partial {
  background: #fef3c7;
  color: #b45309;
}

.status-dot.no {
  background: #fee2e2;
  color: #dc2626;
}

.expand-btn {
  font-size: 1.25rem;
  color: #9ca3af;
  width: 22px;
  text-align: center;
}

.card-body {
  padding: 0 1rem 1rem;
  border-top: 1px solid #e5e7eb;
}

.hint {
  font-size: 0.85rem;
  color: #6b7280;
  font-style: italic;
  margin: 0.75rem 0;
  padding-left: 0.75rem;
  border-left: 3px solid #e5e7eb;
}

.signals {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 0.5rem;
  margin-bottom: 0.75rem;
}

@media (max-width: 500px) {
  .signals {
    grid-template-columns: 1fr;
  }
}

.signal {
  display: flex;
  gap: 0.5rem;
  padding: 0.5rem;
  border-radius: 0.5rem;
  font-size: 0.8rem;
}

.signal.good {
  background: #ecfdf5;
}

.signal.warning {
  background: #fffbeb;
}

.signal-icon {
  width: 20px;
  height: 20px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 0.7rem;
  flex-shrink: 0;
  margin-top: 2px;
}

.signal.good .signal-icon {
  background: #10b981;
  color: white;
}

.signal.warning .signal-icon {
  background: #f59e0b;
  color: white;
}

.signal strong {
  display: block;
  font-size: 0.7rem;
  margin-bottom: 0.15rem;
}

.signal.good strong {
  color: #059669;
}

.signal.warning strong {
  color: #b45309;
}

.signal p {
  color: #4b5563;
  line-height: 1.3;
}

.response-row {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  flex-wrap: wrap;
}

.response-label {
  font-size: 0.8rem;
  color: #374151;
  font-weight: 500;
}

.response-buttons {
  display: flex;
  gap: 0.35rem;
}

.resp-btn {
  padding: 0.4rem 0.75rem;
  border: 2px solid #e5e7eb;
  border-radius: 0.4rem;
  background: white;
  font-size: 0.8rem;
  font-weight: 500;
  cursor: pointer;
  transition: all 0.15s;
}

.resp-btn.yes:hover, .resp-btn.yes.selected {
  background: #d1fae5;
  border-color: #10b981;
  color: #059669;
}

.resp-btn.partial:hover, .resp-btn.partial.selected {
  background: #fef3c7;
  border-color: #f59e0b;
  color: #b45309;
}

.resp-btn.no:hover, .resp-btn.no.selected {
  background: #fee2e2;
  border-color: #ef4444;
  color: #dc2626;
}

.results-panel {
  background: white;
  border-radius: 1rem;
  padding: 1.25rem;
  box-shadow: 0 8px 30px rgba(0, 0, 0, 0.15);
  position: sticky;
  top: 1.5rem;
  height: fit-content;
}

.results-panel h3 {
  font-size: 1.1rem;
  color: #1f2937;
  margin-bottom: 1rem;
}

.score-row {
  display: flex;
  gap: 0.5rem;
  margin-bottom: 1rem;
}

.score-item {
  flex: 1;
  text-align: center;
  padding: 0.5rem;
  border-radius: 0.5rem;
}

.score-item.yes {
  background: #d1fae5;
}

.score-item.partial {
  background: #fef3c7;
}

.score-item.no {
  background: #fee2e2;
}

.score-num {
  display: block;
  font-size: 1.5rem;
  font-weight: 700;
}

.score-item.yes .score-num {
  color: #059669;
}

.score-item.partial .score-num {
  color: #b45309;
}

.score-item.no .score-num {
  color: #dc2626;
}

.score-lbl {
  font-size: 0.65rem;
  text-transform: uppercase;
  color: #6b7280;
}

.verdict-box {
  padding: 0.75rem;
  border: 2px solid;
  border-radius: 0.5rem;
  margin-bottom: 1rem;
}

.verdict-box p {
  font-size: 0.85rem;
  font-weight: 500;
  margin: 0;
  line-height: 1.4;
}

.gaps-section, .strengthen-section {
  margin-bottom: 0.75rem;
}

.gaps-section {
  background: #fef2f2;
  padding: 0.75rem;
  border-radius: 0.5rem;
}

.strengthen-section {
  background: #fffbeb;
  padding: 0.75rem;
  border-radius: 0.5rem;
}

.gaps-section h4 {
  font-size: 0.75rem;
  color: #dc2626;
  margin-bottom: 0.35rem;
}

.strengthen-section h4 {
  font-size: 0.75rem;
  color: #b45309;
  margin-bottom: 0.35rem;
}

.gaps-section ul, .strengthen-section ul {
  list-style: none;
  padding: 0;
}

.gaps-section li, .strengthen-section li {
  font-size: 0.75rem;
  padding-left: 0.75rem;
  position: relative;
  margin-bottom: 0.2rem;
  line-height: 1.3;
}

.gaps-section li {
  color: #991b1b;
}

.strengthen-section li {
  color: #92400e;
}

.gaps-section li::before {
  content: '!';
  position: absolute;
  left: 0;
  font-weight: bold;
}

.strengthen-section li::before {
  content: '~';
  position: absolute;
  left: 0;
}

.footer-note {
  background: rgba(255, 255, 255, 0.95);
  border-radius: 0.75rem;
  padding: 1rem;
  font-size: 0.9rem;
  color: #374151;
}

.footer-note strong {
  color: #059669;
}
